using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.Mvc;
namespace AILearnAPI.Api.Features.NotesRecall;
[ApiController,Route("api/notes"),Authorize(AuthenticationSchemes=JwtBearerDefaults.AuthenticationScheme)]public sealed class NotesRecallController:ControllerBase{readonly NotesRecallService s;public NotesRecallController(NotesRecallService x)=>s=x;string U=>User.FindFirstValue(JwtRegisteredClaimNames.Sub)??User.FindFirstValue(ClaimTypes.NameIdentifier)??"";[HttpPost("{noteId}/recall/generate")]public async Task<ActionResult<NoteRecallContent>>Generate(string noteId,[FromQuery]bool force,CancellationToken ct)=>Ok(await s.Generate(U,noteId,force,ct));[HttpGet("{noteId}/recall")]public async Task<ActionResult<NoteRecallContent>>Get(string noteId){var x=await s.Get(U,noteId);return x==null?NotFound():Ok(x);}[HttpPost("recall/generate-from-selection")][HttpPost("recall/sessions")]public async Task<ActionResult<NoteRecallSession>>Create(CreateRecallSessionRequest r,CancellationToken ct)=>Ok(await s.Create(U,r,ct));[HttpGet("recall/sessions/{id}")]public async Task<ActionResult<NoteRecallSession>>Session(string id){var x=await s.Session(U,id);return x==null?NotFound():Ok(x);}[HttpPost("recall/sessions/{id}/answer")]public async Task<ActionResult<NoteRecallAttempt>>Answer(string id,RecallAnswerRequest r,CancellationToken ct)=>Ok(await s.Answer(U,id,r,ct));[HttpPost("recall/sessions/{id}/reveal")]public IActionResult Reveal(string id)=>Ok(new{assisted=true});[HttpPost("recall/sessions/{id}/complete")]public IActionResult Complete(string id)=>Ok(new{completed=true});[HttpGet("recall/due")]public async Task<ActionResult<List<NoteRecallItem>>>Due()=>Ok(await s.Due(U));[HttpGet("recall/dashboard")]public async Task<ActionResult<RecallDashboard>>Dashboard()=>Ok(await s.Dashboard(U));[HttpGet("recall/weak")]public async Task<ActionResult<List<NoteRecallItem>>>Weak()=>Ok((await s.Due(U)).Where(x=>x.AverageRecallScore<6));[HttpPatch("recall/items/{id}/mastered")]public async Task<ActionResult<NoteRecallItem>>Master(string id,[FromBody]bool mastered)=>Ok(await s.Master(U,id,mastered));}
